export interface KruitboschDetailResponse {
  eanUpc: string
  color: string | null
  vatRateBasisPoints: number
  fullDescription: string | null
}

/**
 * Fetch detailed product information for a Kruitbosch product by EAN.
 * Returns null if the product is not found in the local catalog.
 */
export async function getKruitboschDetail(ean: string): Promise<KruitboschDetailResponse | null> {
  const trimmedEan = ean.trim()

  const results = await db.select({
    eanUpc: kruitboschProducts.eanUpc,
    color: kruitboschProducts.color,
    vatRateBasisPoints: kruitboschProducts.vatRateBasisPoints,
    fullDescription: kruitboschProducts.description,
  })
    .from(kruitboschProducts)
